#!/usr/bin/env bash
set -euo pipefail

# Trinity Compress Installer (Bash)
# Installs Trinity Compress assets into the current repository

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(dirname "$SCRIPT_DIR")"

echo "Trinity Compress Installer"
echo "=========================="

# Check requirements
for cmd in jq bc; do
    if ! command -v "$cmd" &>/dev/null; then
        echo "Warning: $cmd is not installed. Trinity Compress requires it."
        echo "Install with: apt-get install $cmd"
