      "keystrokes": "cat > scripts/install.ps1 << 'EOF'
#!/usr/bin/env pwsh
# Trinity Compress Installer (PowerShell)
# Installs Trinity Compress assets into the current repository

Write-Host "Trinity Compress Installer" -ForegroundColor Cyan
Write-Host "=========================="

$RootDir = $PSScriptRoot | Split-Path -Parent

# Check requirements
foreach ($cmd in @("jq", "bc")) {
    if (-not (Get-Command $cmd -ErrorAction SilentlyContinue)) {
        Write-Warning "$cmd is not installed. Trinity Compress requires it."
    }
}

# Create config if not exists
$ConfigFile = Join-Path $RootDir "trinity-compress.config.json"
if (-not (Test-Path $ConfigFile)) {
    $config = @{
        mode = "balanced"
        targets = @("prompts/system.md", "prompts/developer.md", "prompts/user.md")
        preserve = @("code_blocks", "urls", "file_paths", "variable_names")
    }
    $config | ConvertTo-Json | Out-File -FilePath $ConfigFile
    Write-Host "Created: trinity-compress.config.json"
}

# Create Makefile if not exists
$Makefile = Join-Path $RootDir "Makefile"
if (-not (Test-Path $Makefile)) {
    $makefileContent = @'
.PHONY: optimize-prompts optimize-undo optimize-status help

help:
	@echo "Trinity Compress Makefile Targets:"
	@echo "  optimize-prompts  - Compress prompt files (balanced mode)"
	@echo "  optimize-undo     - Restore original files from backups"
	@echo "  optimize-status   - Show status of compressed files"

optimize-prompts:
	@bash scripts/trinity-compress.sh balanced compress

optimize-undo:
	@bash scripts/trinity-compress.sh undo

optimize-status:
	@bash scripts/trinity-compress.sh status
'@
    $makefileContent | Out-File -FilePath $Makefile
    Write-Host "Created: Makefile"
}

# Add .gitignore entry if not present
$Gitignore = Join-Path $RootDir ".gitignore"
if (Test-Path $Gitignore) {
    if (-not (Select-String -Path $Gitignore -Pattern "\.bak" -Quiet)) {
        Add-Content -Path $Gitignore -Value ""
        Add-Content -Path $Gitignore -Value "# Trinity Compress backups"
        Add-Content -Path $Gitignore -Value "*.bak"
        Write-Host "Added: *.bak to .gitignore"
    }
} else {
    "# Trinity Compress backups`n*.bak" | Out-File -FilePath $Gitignore
    Write-Host "Created: .gitignore"
}

Write-Host "=========================="
Write-Host "Installation complete!"
Write-Host "Run 'make optimize-prompts' or 'bash scripts/trinity-compress.sh balanced'"
EOF
chmod +x scripts/install.ps1\n",
